const tabId = 2017691829;
const answer = await browserjs(tabId, () => {
  const headings = Array.from(document.querySelectorAll('h2, h3, h4, button, summary, div, span'));
  const target = headings.find(el => el.textContent?.trim() === 'Do you travel?');
  if (target) {
    // try to find sibling or child
    let curr = target;
    for (let i = 0; i < 5; i++) {
      if (curr.nextElementSibling) {
        return curr.nextElementSibling.innerText;
      }
      if (curr.parentElement) curr = curr.parentElement;
    }
  }
  return 'Not found';
});
console.log("Travel FAQ answer:", answer);

