const tabId = 2017691829;
const moreDetails = await browserjs(tabId, () => {
  const sections = Array.from(document.querySelectorAll('section, div')).filter(el => {
    const t = el.innerText || '';
    return t.includes('Global') || t.includes('Travel') || t.includes('Inquire') || t.includes('Contact') || t.includes('Bridal');
  });
  return {
    contactInfo: document.querySelector('form')?.outerHTML || 'No form found',
    fullText: document.body.innerText
  };
});

// Let's find travel details and contact details in the text
const lines = moreDetails.fullText.split('\n').filter(l => l.trim().length > 0);
console.log("Lines matching travel/booking/wedding/location:");
for (let i = 0; i < lines.length; i++) {
  const l = lines[i];
  if (/travel|destination|international|global|wedding|inquire|book|contact|pricing|location|region/i.test(l)) {
    console.log(`[${i}] ${l}`);
  }
}

