const tabId = 2017691829;
const answer = await browserjs(tabId, () => {
  const details = Array.from(document.querySelectorAll('details'));
  const found = details.find(d => d.innerText.includes('outside London'));
  if (found) {
    found.open = true;
    return found.innerText;
  }
  // Try buttons or summaries
  const buttons = Array.from(document.querySelectorAll('button, summary, [role="button"]'));
  const btn = buttons.find(b => b.innerText.includes('outside London'));
  if (btn) {
    btn.click();
    return btn.parentElement?.innerText;
  }
  return 'Not found in details/buttons';
});
console.log("CD Noir travel FAQ:", answer);

